def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    paths = glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Fraud and Other data/*.csv')
    rows = []
    for p in sorted(paths)[:5]:
        df = pd.read_csv(p)
        rows.append({'file': os.path.basename(p), 'nrows': df.shape[0], 'ncols': df.shape[1], 'columns': list(df.columns)})
    return pd.DataFrame(rows)

def load() -> pd.DataFrame:
    import glob, os
    import pandas as pd

    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Fraud and Other data/*.csv'
    files = sorted(glob.glob(pattern))
    return pd.DataFrame({'file': [os.path.basename(f) for f in files], 'path': files})

