def process(msa_clean):
    import pandas as pd
    counts = msa_clean.groupby('state', as_index=False).agg(n_metros=('metro_area','nunique'), state_reports=('reports','sum'))
    return counts.sort_values(['n_metros','state'], ascending=[False, True])

def process(state_metro_counts):
    import pandas as pd
    df = state_metro_counts.copy()
    return df[df['n_metros'] >= 5].reset_index(drop=True)
